"use client";

import * as React from "react";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { formFieldBase, formFieldSingleLine } from "./_shared";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "./command";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

const cities = [
  { value: "lisbon", label: "Lisbon" },
  { value: "nairobi", label: "Nairobi" },
  { value: "seoul", label: "Seoul" },
  { value: "toronto", label: "Toronto" },
  { value: "mexico-city", label: "Mexico City" },
];

/**
 * Firefly combobox: a field that opens a searchable list. The trigger is the
 * warm paper well every text field uses, with a sort glyph at the end. The
 * list drops onto the raised white panel, as wide as the trigger, and the
 * chosen row carries a near-black tick.
 */
export function ComboboxDemo() {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");
  const selected = cities.find((city) => city.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        role="combobox"
        aria-expanded={open}
        data-slot="combobox-trigger"
        className={cn(
          formFieldBase,
          formFieldSingleLine,
          "w-56 cursor-default items-center justify-between gap-2 text-start",
          "data-[popup-open]:border-(--accent-line)",
          !selected && "text-muted-foreground",
        )}
      >
        <span className="truncate">{selected ? selected.label : "Select a city"}</span>
        <Icon
          icon="carbon:caret-sort"
          className="size-4 shrink-0 text-muted-foreground"
          aria-hidden="true"
        />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--anchor-width) gap-0 p-0">
        <Command className="bg-transparent shadow-none">
          <CommandInput placeholder="Search cities" />
          <CommandList>
            <CommandEmpty>No city found.</CommandEmpty>
            <CommandGroup>
              {cities.map((city) => (
                <CommandItem
                  key={city.value}
                  value={city.value}
                  onSelect={(currentValue: string) => {
                    setValue(currentValue === value ? "" : currentValue);
                    setOpen(false);
                  }}
                >
                  {city.label}
                  <Icon
                    icon="carbon:checkmark"
                    className={cn(
                      "ms-auto size-4",
                      value === city.value ? "opacity-100" : "opacity-0",
                    )}
                    aria-hidden="true"
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
